      "quote": "Accuracy of novel antigen rapid diagnostics for SARS-CoV-2: A living systematic review and meta-analysis",
      "reason": "The title explicitly identifies the work as a “living systematic review and meta-analysis,” indicating it is a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Accuracy of novel antigen rapid diagnostics for SARS-CoV-2: A living systematic review and meta-analysis",
      "reason": "The title provides the main objective (“Accuracy of … diagnostic tests”) and the focus/population context (“SARS-CoV-2” using “antigen rapid diagnostics”)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Accuracy of novel antigen rapid diagnostics for SARS-CoV-2: A living systematic review and meta-analysis",
      "reason": "The title includes relevant supplementary information for PRISMA 2020 item 1, specifically the living-review status (“living”) and that a meta-analysis is included (“meta-analysis”)."
    }
  ],
  "confidence": 78
