{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Initial data from independent evaluations suggest that the performance of SARS-CoV-2 Ag-RDTs may be lower than what is reported by the manufacturers. In addition, Ag-RDT accuracy seems to vary substantially between tests [4-6]. With the increased availability of Ag-RDTs, an increasing number of independent validations have been published. Such evaluations differ widely in their quality, methods, and results, making it difficult to assess the true performance of the respective tests [7].",
      "reason": "Describes the current state of knowledge (independent evaluations vs manufacturers; variability between tests) and an important uncertainty (difficulty assessing true performance due to differences in study quality/methods/results)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "To inform decision makers on the best choice of individual tests, an aggregated, widely available, and frequently updated assessment of the quality, performance, and independence of the data is urgently needed.",
      "reason": "Explains the importance and need for conducting the review for decision makers, emphasizing an urgent need for aggregated, up-to-date evidence on quality/performance/independence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "While other systematic reviews have been published, they include data only up until November 2020 [8-11], exclude preprints [12], or were industry sponsored [13]. In addition, only 1 assessed the quality of studies in detail, with data up until November 2020 [7,11]. With our systematic review and meta-analysis, we aim to close this gap in the literature and link to a website (https://www.diagnosticsglobalhealth.org) that is regularly updated.",
      "reason": "Identifies previous systematic reviews and explains how the current review addresses limitations (time cut-off, exclusion of preprints, industry sponsorship, limited detailed quality assessment), and states the aim to close this gap."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": "antigen rapid diagnostic tests (AgRDTs) for SARS-CoV-2 are seen as an important diagnostic tool to fight the virus's spread",
      "reason": "The criterion is specifically for reviews of intervention effects. The provided evidence indicates the work is about diagnostic test accuracy (Ag-RDTs), so a proposed mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": "antigen rapid diagnostic tests (AgRDTs) for SARS-CoV-2 are seen as an important diagnostic tool to fight the virus's spread",
      "reason": "The criterion is specifically for complex interventions/delivery contexts using a logic model. The provided evidence frames the review around diagnostic tests rather than a complex intervention, so a logic model is not applicable."
    }
  ],
  "confidence": 72
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "With our systematic review and meta-analysis, we aim to close this gap in the literature and link to a website (https://www.diagnosticsglobalhealth.org) that is regularly updated.",
      "reason": "The manuscript states an aim (“we aim to close this gap… and link to a website…”), but the objectives/questions are not clearly presented in an explicit question-formulation framework."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_1",
      "quote": "In this systematic review and meta-analysis, we assessed the clinical accuracy (sensitivity and specificity) of commercially available Ag-RDTs.",
      "reason": "This is a diagnostic accuracy review rather than a review of intervention effects; therefore, the conditional requirement for planned comparisons stated using PICO (or variant) does not apply."
    }
  ],
  "confidence": 62
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "Weincluded studies evaluating the accuracy of commercially available Ag-RDTs to establish a diagnosis of SARS-CoV-2 infection, against reverse transcription polymerase chain reaction (RT-PCR) or cell culture as reference standard. We included all study populations irrespective of age, presence of symptoms, or study location. We considered cohort studies, nested cohort studies, case-control or cross-sectional studies, and randomized studies.",
      "reason": "Eligibility characteristics used to determine eligibility are partially specified (reference standard, populations irrespective of age/symptoms/location, and eligible study designs). However, the evidence does not specify eligible settings and follow-up requirements."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "We included both peer-reviewed publications and preprints.",
      "reason": "The evidence specifies publication status (peer-reviewed and preprints). It also reports language in the Results, but it does not specify dissemination year (or other report characteristics) in the Methods inclusion/exclusion criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided distinguishing exclusions due to outcomes not measured versus outcomes not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "Wedifferentiated between clinical accuracy studies (performed on clinical samples) and analytical accuracy studies (performed on spiked samples with a known quantity of virus). ... we only considered data from clinical accuracy studies as eligible for the meta-analysis. Separately, we summarized the results of analytical studies and compared them with the results of the meta-analysis for individual tests.",
      "reason": "The review distinguishes groups used for syntheses (clinical vs analytical accuracy) and indicates which group is eligible for the meta-analysis. However, the evidence does not clearly state that these groups are linked to specific comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Also, publications with a population size smaller than 10 were excluded. Although the size threshold of 10 is arbitrary, such small studies are more likely to give unreliable estimates of sensitivity and specificity.",
      "reason": "A rationale is provided for a notable eligibility restriction (excluding studies with population size <10 due to unreliability of sensitivity/specificity estimates)."
    }
  ],
  "confidence": 72
}

